const rawOutput = $input.first().json.output;

if (!rawOutput) {
  throw new Error('❌ No output from Stage 1. Expected json.output field.');
}

let jsonString = typeof rawOutput === 'string' ? rawOutput : String(rawOutput);
jsonString = jsonString.trim();

// Remove markdown code blocks
jsonString = jsonString.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
jsonString = jsonString.trim();

const jsonStart = jsonString.indexOf('{');
const jsonEnd = jsonString.lastIndexOf('}');

if (jsonStart === -1 || jsonEnd === -1) {
  throw new Error('❌ No JSON object found in output');
}

jsonString = jsonString.substring(jsonStart, jsonEnd + 1);

let plan;
try {
  plan = JSON.parse(jsonString);
} catch (parseError) {
  throw new Error(`❌ Invalid JSON: ${parseError.message}`);
}

// === DETECT FORMAT ===
const hasStages = plan.stages && typeof plan.stages === 'object' && !Array.isArray(plan.stages);
const hasTasks = plan.tasks && Array.isArray(plan.tasks);

if (!hasStages && !hasTasks) {
  throw new Error('❌ Missing: must have either "stages" (object) or "tasks" (array)');
}

// === COMMON VALIDATION ===
if (!plan.buildingRequest) {
  throw new Error('❌ Missing: buildingRequest');
}

if (!plan.metadata) {
  throw new Error('❌ Missing: metadata');
}

if (!plan.workerCount || plan.workerCount < 1) {
  throw new Error('❌ Missing or invalid: workerCount (must be >= 1)');
}

// === FORMAT-SPECIFIC VALIDATION ===

if (hasStages) {
  // Multi-stage format validation
  const stageKeys = Object.keys(plan.stages)
    .map(k => parseInt(k))
    .sort((a, b) => a - b);

  if (stageKeys.length === 0) {
    throw new Error('❌ stages object is empty');
  }

  const expectedSequence = Array.from(
    { length: Math.max(...stageKeys) },
    (_, i) => i + 1
  );

  if (JSON.stringify(stageKeys) !== JSON.stringify(expectedSequence)) {
    throw new Error(`❌ Stages not sequential. Found: [${stageKeys}], Expected: [${expectedSequence}]`);
  }

  // Validate workers in all stages
  const expectedWorkerCount = plan.workerCount;
  for (let stageNum of stageKeys) {
    const stage = plan.stages[stageNum.toString()];
    const tasks = stage.tasks || {};
    const workersInStage = Object.keys(tasks).filter(k => k.startsWith('Worker')).length;

    if (workersInStage !== expectedWorkerCount) {
      throw new Error(
        `❌ Stage ${stageNum} has ${workersInStage} workers, expected ${expectedWorkerCount}`
      );
    }

    // Validate coordinates
    for (let workerNum = 1; workerNum <= expectedWorkerCount; workerNum++) {
      const worker = tasks[`Worker${workerNum}`];
      if (!worker || !worker.subtask || worker.subtask === 'rest') continue;

      if (!worker.coordinates) {
        throw new Error(`❌ Stage ${stageNum} Worker${workerNum} missing coordinates`);
      }

      const requiredCoords = ['xMin', 'xMax', 'yMin', 'yMax', 'zMin', 'zMax'];
      for (let coord of requiredCoords) {
        if (worker.coordinates[coord] === undefined) {
          throw new Error(
            `❌ Stage ${stageNum} Worker${workerNum} missing coordinate: ${coord}`
          );
        }
        if (typeof worker.coordinates[coord] !== 'number') {
          throw new Error(
            `❌ Stage ${stageNum} Worker${workerNum} ${coord} must be number`
          );
        }
      }
    }
  }

  console.log('✅ Multi-stage plan parsed successfully');
  console.log(`   Stages: ${stageKeys.length}`);
  console.log(`   Workers: ${expectedWorkerCount}`);
  console.log(`   Building: ${plan.buildingRequest}`);

  return {
    success: true,
    format: 'multi-stage',
    plan: plan,
    validation: {
      stageCount: stageKeys.length,
      workerCount: expectedWorkerCount,
      stagesPerWorker: stageKeys.length / expectedWorkerCount,
      totalWorkerTasks: stageKeys.length * expectedWorkerCount
    }
  };

} else if (hasTasks) {
  // Flat task array format validation
  if (!Array.isArray(plan.tasks) || plan.tasks.length === 0) {
    throw new Error('❌ tasks must be non-empty array');
  }

  plan.tasks.forEach((task, idx) => {
    if (!task.stageNumber) throw new Error(`❌ Task ${idx} missing stageNumber`);
    if (!task.worker) throw new Error(`❌ Task ${idx} missing worker`);
    if (!task.port) throw new Error(`❌ Task ${idx} missing port`);
    if (!task.coordinates) throw new Error(`❌ Task ${idx} missing coordinates`);

    const coords = task.coordinates;
    ['xMin', 'xMax', 'yMin', 'yMax', 'zMin', 'zMax'].forEach(c => {
      if (typeof coords[c] !== 'number') {
        throw new Error(`❌ Task ${idx} coordinates.${c} must be number`);
      }
    });
  });

  console.log('✅ Flat task plan parsed successfully');
  console.log(`   Tasks: ${plan.tasks.length}`);
  console.log(`   Workers: ${plan.workerCount}`);
  console.log(`   Building: ${plan.buildingRequest}`);

  return {
    success: true,
    format: 'flat-tasks',
    plan: plan,
    validation: {
      taskCount: plan.tasks.length,
      workerCount: plan.workerCount,
      buildingRequest: plan.buildingRequest
    }
  };
}

