let input = $('Webhook').first().json.body.instructions.location;
let location = input;
// If location is "unspecified", use botStatus position instead
if (input === 'unspecified' || input === 'default'  || !input) {
  location = $input.first().json.position;
}

let coordinates;

if (typeof location === 'string') {
  const match = location.match(/x:\s*(-?\d+\.?\d*),\s*y:\s*(-?\d+\.?\d*),\s*z:\s*(-?\d+\.?\d*)/);
  if (match) {
    coordinates = {
      x: Math.floor(parseFloat(match[1])),
      y: Math.floor(parseFloat(match[2])),
      z: Math.floor(parseFloat(match[3]))
    };
  }
} else if (typeof location === 'object' && location !== null) {
  coordinates = {
    x: Math.floor(location.x),
    y: Math.floor(location.y),
    z: Math.floor(location.z)
  };
}

return {
  coordinates: coordinates || {},
}

const plan = $input.first().json.plan;
const spawnedWorkers = $('SpawnWorkers').first().json.spawnedWorkers;;

if (!plan || !plan.stages) {
  throw new Error('❌ No plan with stages found');
}

if (!spawnedWorkers || !Array.isArray(spawnedWorkers) || spawnedWorkers.length === 0) {
  throw new Error('❌ No spawned workers provided');
}

// Build worker mapping: Worker1 -> TheBoss_W1, Worker2 -> TheBoss_W2, etc.
const workerMap = {};
spawnedWorkers.forEach((worker, index) => {
  const placeholderName = `Worker${index + 1}`;
  workerMap[placeholderName] = {
    name: worker.workerName,
    port: worker.port,
    status: worker.status
  };
});

console.log('📋 Worker mapping:');
Object.entries(workerMap).forEach(([placeholder, actual]) => {
  console.log(`   ${placeholder} → ${actual.name} (port ${actual.port})`);
});

// Deep clone plan to avoid mutating original
const updatedPlan = JSON.parse(JSON.stringify(plan));

// Traverse all stages and replace worker references
Object.values(updatedPlan.stages).forEach((stage, stageIndex) => {
  const stageNum = stageIndex + 1;
  const newTasks = {};

  Object.entries(stage.tasks).forEach(([placeholderWorker, taskData]) => {
    if (!workerMap[placeholderWorker]) {
      throw new Error(`❌ Stage ${stageNum}: No spawned worker found for ${placeholderWorker}`);
    }

    const actualWorker = workerMap[placeholderWorker];

    // Update task data with actual worker name and port
    const updatedTask = {
      ...taskData,
      worker: actualWorker.name,
      port: actualWorker.port
    };

    // Replace worker name in fullPrompt if present
    if (updatedTask.fullPrompt && updatedTask.fullPrompt.includes(placeholderWorker)) {
      updatedTask.fullPrompt = updatedTask.fullPrompt.replaceAll(
        placeholderWorker,
        actualWorker.name
      );
    }

    newTasks[actualWorker.name] = updatedTask;
  });

  stage.tasks = newTasks;
});

// Update metadata worker references if present
if (updatedPlan.metadata && updatedPlan.metadata.worker1XRange) {
  // Update any worker-specific metadata fields
  Object.keys(updatedPlan.metadata).forEach(key => {
    if (key.match(/worker\d+/i)) {
      const workerNum = key.match(/\d+/)[0];
      const placeholder = `Worker${workerNum}`;

      if (workerMap[placeholder]) {
        const newKey = key.replace(/worker\d+/i, workerMap[placeholder].name.toLowerCase());
        updatedPlan.metadata[newKey] = updatedPlan.metadata[key];
        delete updatedPlan.metadata[key];
      }
    }
  });
}

// Update taskDivision if present
if (updatedPlan.taskDivision) {
  const newTaskDivision = {};

  Object.entries(updatedPlan.taskDivision).forEach(([placeholderWorker, divisionData]) => {
    if (workerMap[placeholderWorker]) {
      const actualWorker = workerMap[placeholderWorker];
      newTaskDivision[actualWorker.name] = divisionData;
    }
  });

  updatedPlan.taskDivision = newTaskDivision;
}

console.log('✅ Plan updated with actual worker names');
console.log(`   Stages: ${Object.keys(updatedPlan.stages).length}`);
console.log(`   Workers: ${spawnedWorkers.length}`);

return {
  success: true,
  plan: updatedPlan,
  workerMapping: workerMap,
  message: `Plan updated: ${spawnedWorkers.map(w => w.workerName).join(', ')}`
};
